\subsection{Problem Setup}
\label{sec:setup}

Let $\mathcal{D} = \mathcal{D}_{\mathrm{real}} \cup \mathcal{D}_{\mathrm{synth}}$ denote a pretraining corpus with contamination ratio $\rho = |\mathcal{D}_{\mathrm{synth}}| / |\mathcal{D}|$, assumed unknown~\citep{cheng2025contamination}.
A detector assigns each sample $x$ a synthetic probability $q(x) \in [0,1]$; following \citet{drayson2025detection}, we weight each sample as
\begin{equation}
  w(x) = (1 - q(x))^{b},
  \label{eq:weight}
\end{equation}
where $b \geq 0$ is a sharpening exponent: $b = 0$ recovers uniform training, while larger $b$ suppresses high-$q$ samples.
\citet{drayson2025detection} select $b$ via validation-set grid search ($b{=}10$ for ${\leq}360$M, $b{=}1$ for 1.7B); we instead derive $b$ per-batch from the batch's $q$-score distribution.

\subsection{Dual-Constraint Framework}
\label{sec:dual}

Given a batch $\mathcal{B} = \{x_1, \ldots, x_B\}$ with scores $q_i = q(x_i)$ and weights $w_i(b) = (1 - q_i)^{b}$, we define two diagnostics.

\paragraph{Effective real proportion.}
Let $r_i = \mathbf{1}[q_i \leq 0.5]$ estimate whether $x_i$ is human-authored.
The \emph{effective real proportion}
\begin{equation}
  \alpha_{\mathrm{eff}}(b) = \frac{\sum_{i=1}^{B} w_i(b) \cdot r_i}{\sum_{i=1}^{B} w_i(b)}
  \label{eq:alpha}
\end{equation}
measures the share of weight allocated to likely-real samples.
Since $r_i$ is binary, $\aeff(0)$ takes only $B{+}1$ discrete values; however, for $b > 0$ the weights $w_i(b)$ vary continuously in $b$, making $\aeff(b)$ a continuous function amenable to bisection.
$\aeff$ is a proxy for the true real fraction (Pearson $r \approx 0.70$; Appendix~\ref{app:alpha_validation}); post-hoc calibration~\citep{guo2017calibration} yields ECE\,=\,0.05.

\paragraph{Effective sample size.}
Kish's effective sample size~\citep{kish1965survey}
\begin{equation}
  \mathrm{ESS}(b) = \frac{\bigl(\sum_{i=1}^{B} w_i(b)\bigr)^{2}}{\sum_{i=1}^{B} w_i(b)^{2}}
  \label{eq:ess}
\end{equation}
quantifies how many equally-weighted samples the weighted batch is equivalent to; $\mathrm{ESS}(0) = B$ and $\mathrm{ESS}$ decreases monotonically in $b$ (Proposition~\ref{prop:ess_mono}, Appendix~\ref{app:proofs}).

\paragraph{Dual constraints.}
$\alpha_{\mathrm{eff}}(b)$ is non-decreasing (Proposition~\ref{prop:monotone}) and $\mathrm{ESS}(b)$ is decreasing, yielding opposing bounds on $b$:
\begin{enumerate}[nosep,leftmargin=*]
  \item \textbf{Quality floor}: $\alpha_{\mathrm{eff}}(b) \geq \tau$ defines a lower bound $b_\tau$, motivated by convergence theory under contamination~\citep{wang2026survive}.
  Note: \citet{wang2026survive} assume known $\alpha$; we replace it with estimated $\aeff(b)$, so the guarantee holds modulo detector calibration.
  \item \textbf{Stability ceiling}: $\mathrm{ESS}(b) \geq n_{\min}$ defines an upper bound $b_{\mathrm{ESS}}$, preventing gradient degeneration from weight concentration.
\end{enumerate}
The optimal sharpening exponent is
\begin{equation}
  b^{*} = \begin{cases}
    0        & \text{if } \alpha_{\mathrm{eff}}(0) \geq \tau, \\
    b_\tau   & \text{if } b_\tau \leq b_{\mathrm{ESS}}, \\
    b_{\mathrm{ESS}} & \text{otherwise},
  \end{cases}
  \label{eq:bstar}
\end{equation}
implementing \emph{minimum intervention}: apply the smallest $b$ that achieves the quality floor.
When constraints conflict ($b_\tau > b_{\mathrm{ESS}}$), stability takes precedence.
Each batch falls into one of three regimes---clean ($\aeff(0) \geq \tau$), $\aeff$-binding ($b^{*} = b_\tau$), or ESS-binding ($b^{*} = b_{\mathrm{ESS}}$)---whose relative frequencies we report in \S\ref{sec:regime}.

\paragraph{Implementation.}
$b^{*}$ is found via bisection on $\aeff(\cdot)$ and $\mathrm{ESS}(\cdot)$; given $b^{*}$, normalized weights $\pi_i = w_i(b^{*}) / \sum_j w_j(b^{*})$ define the weighted loss $\mathcal{L} = \sum_i \pi_i \ell_i$ (Algorithm~\ref{alg:bstar}, Appendix~\ref{app:algorithm}).
This \emph{loss reweighting} maintains continuous gradients, unlike the SIR resampling of \citet{drayson2025detection}.
Default hyperparameters are $\tau{=}0.7$ and $\nmin{=}\lfloor B/2 \rfloor$; sensitivity analysis in \S\ref{sec:sensitivity}.

